def coalesce(intervals):
    """
    Merge overlapping or touching half-open integer intervals (start, end).

    - Discards empty intervals (start == end).
    - Raises ValueError if any interval has start > end.
    - Returns a sorted list of tuples, without mutating the input.
    """
    valid = []
    for interval in intervals:
        start, end = interval
        if start > end:
            raise ValueError(
                f"Invalid interval ({start}, {end}): start > end"
            )
        if start < end:
            valid.append((start, end))

    if not valid:
        return []

    valid.sort()

    merged = [valid[0]]
    for start, end in valid[1:]:
        if start <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))
        else:
            merged.append((start, end))

    return merged
```

