import copy


def merge(base, overlay):
    """Recursively merge two JSON-like dictionaries into a new result.

    - Overlay values replace base values (including lists and None).
    - A None in overlay replaces the value but does not delete the key.
    - Nested dicts are merged recursively; all other types are replaced.
    - The result is deep-independent: no nested input data is mutated or aliased.
    """
    result = {}

    for key, base_val in base.items():
        if key in overlay:
            overlay_val = overlay[key]
            if isinstance(base_val, dict) and isinstance(overlay_val, dict):
                result[key] = merge(base_val, overlay_val)
            else:
                result[key] = copy.deepcopy(overlay_val)
        else:
            result[key] = copy.deepcopy(base_val)

    for key, overlay_val in overlay.items():
        if key not in base:
            result[key] = copy.deepcopy(overlay_val)

    return result
```

