def flatten(value):
    if not isinstance(value, dict):
        return value
    if len(value) == 0:
        return {}
    result = {}
    for key, sub in value.items():
        if isinstance(sub, dict) and len(sub) > 0:
            sub_flat = flatten(sub)
            for k, v in sub_flat.items():
                result[f"{key}.{k}"] = v
        else:
            result[key] = sub
    return result
