def normalize(path: str) -> str:
    """Normalize an absolute POSIX-like path.

    - Rejects non-absolute paths with ValueError.
    - Collapses repeated slashes.
    - Ignores '.' components.
    - Resolves '..' components without going above root.
    - Returns '/' for root; never has a trailing slash otherwise.
    """
    if not isinstance(path, str) or not path.startswith("/"):
        raise ValueError(f"not an absolute path: {path!r}")

    stack: list[str] = []
    for part in path.split("/"):
        if part == "" or part == ".":
            continue
        elif part == "..":
            if stack:
                stack.pop()
        else:
            stack.append(part)

    if not stack:
        return "/"
    return "/" + "/".join(stack)
```

