def pack(items, max_bytes):
    if max_bytes < 1:
        raise ValueError("max_bytes must be >= 1")
    for item in items:
        if len(item.encode("utf-8")) > max_bytes:
            raise ValueError("item does not fit in max_bytes")
    if not items:
        return []
    result = []
    current = []
    total = 0
    for item in items:
        blen = len(item.encode("utf-8"))
        if total + blen <= max_bytes:
            current.append(item)
            total += blen
        else:
            result.append(current)
            current = [item]
            total = blen
    if current:
        result.append(current)
    return result
