import heapq


def order(deps):
    # Collect all nodes: keys and any prerequisite-only nodes
    nodes = set(deps.keys())
    for prereqs in deps.values():
        nodes.update(prereqs)

    # In-degree = number of unique prerequisites for each node
    in_degree = {}
    for node in nodes:
        in_degree[node] = len(set(deps[node])) if node in deps else 0

    # Reverse adjacency: prereq -> list of nodes that depend on it
    dependents = {node: set() for node in nodes}
    for node, prereqs in deps.items():
        for prereq in prereqs:
            dependents[prereq].add(node)

    # Min-heap over currently ready (in-degree 0) nodes
    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for dep in dependents[node]:
            in_degree[dep] -= 1
            if in_degree[dep] == 0:
                heapq.heappush(heap, dep)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected in dependency graph")

    return result
```

