def histogram(edges, values):
    if not isinstance(edges, (list, tuple)) or len(edges) < 2:
        raise ValueError("edges must be a list with at least two numbers")
    for i in range(len(edges)):
        if not isinstance(edges[i], (int, float)):
            raise ValueError("edges must contain numbers")
    for i in range(len(edges) - 1):
        if edges[i] >= edges[i + 1]:
            raise ValueError("edges must be strictly increasing")

    n = len(edges)
    counts = [0] * (n - 1)

    for v in values:
        if v < edges[0] or v > edges[-1]:
            continue
        idx = bisect_right(edges, v) - 1
        if idx >= n - 1:
            idx = n - 2
        counts[idx] += 1

    return counts
