def histogram(edges, values):
    if len(edges) < 2:
        raise ValueError("edges must be a strictly increasing list with at least two numbers")
    for i in range(len(edges) - 1):
        if not edges[i] < edges[i + 1]:
            raise ValueError("edges must be a strictly increasing list with at least two numbers")

    m = len(edges)
    num_bins = m - 1
    counts = [0] * num_bins

    low = edges[0]
    high = edges[-1]

    for v in values:
        if v < low or v > high:
            continue
        # Binary search: find rightmost index i in [0, m-1] with edges[i] <= v
        lo, hi = 0, m - 1
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if edges[mid] <= v:
                lo = mid
            else:
                hi = mid - 1
        # lo is the rightmost index where edges[lo] <= v
        if lo == m - 1:
            # v equals the last edge; belongs to the final bin (which includes it)
            counts[num_bins - 1] += 1
        else:
            # edges[lo] <= v < edges[lo+1]; bin index is lo
            counts[lo] += 1

    return counts
